command:
set -eu; . /root/vault-transit.env; vault secrets enable -path=transit transit >/dev/null; vault write -f transit/keys/raft-auto-unseal >/dev/null; cat > /tmp/transit-unseal-policy.hcl <<'INFRAPOLICY'
path "transit/encrypt/raft-auto-unseal" {
  capabilities = ["update"]
}
path "transit/decrypt/raft-auto-unseal" {
  capabilities = ["update"]
}
INFRAPOLICY
vault policy write transit-unseal /tmp/transit-unseal-policy.hcl >/dev/null; rm -f /tmp/transit-unseal-policy.hcl; vault auth enable -path=cert cert >/dev/null; vault write auth/cert/certs/raft-members display_name=raft-auto-unseal certificate=@/etc/vault.d/tls/ca.crt allowed_common_names=node2,node3,node4 token_policies=[REDACTED] token_period=[REDACTED] token_type=[REDACTED] >/dev/null; printf 'TRANSIT_MOUNT\n'; vault secrets list -format=json | jq -r '."transit/" | {type,accessor}'; printf 'TRANSIT_KEY\n'; vault read -format=json transit/keys/raft-auto-unseal | jq '.data | {name,type,latest_version,min_decryption_version,min_encryption_version}'; printf 'CERT_ROLE\n'; vault read -format=json auth/cert/certs/raft-members | jq '.data | {display_name,allowed_common_names,token_policies,token_period}'

